-- Native PostgreSQL schema for the management JWKS cache (event kind 11793).
--
-- This table holds at most one row, ever. The SQLite-derived version spelled
-- that as `singleton BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK
-- (singleton = 1)` -- an identity sequence whose every generated value would
-- violate the column's own CHECK past the first. A boolean primary key that can
-- only be true says the same thing without the contradiction.
--
-- The digests stay BYTEA. They are 32 raw bytes; the wire carries them as hex
-- because it is a text protocol, and converting at the boundary keeps the
-- length constraint meaningful (32 bytes, not 64 characters that might not be
-- hex).
--
-- envelope_bytes becomes TEXT. The C bound a C string into a blob column and
-- read it back with memcpy plus a NUL, so it was text wearing a blob's type;
-- the length bound is unchanged for the ASCII the envelope actually carries.

CREATE TABLE IF NOT EXISTS server_management_jwks_cache (
  singleton           BOOLEAN PRIMARY KEY DEFAULT true CHECK (singleton),
  generation          BIGINT NOT NULL CHECK (generation = 1),
  valid_from          BIGINT NOT NULL CHECK (valid_from >= 0),
  valid_until         BIGINT NOT NULL CHECK (valid_until > valid_from),
  jwks_bytes          BYTEA  NOT NULL CHECK (length(jwks_bytes) BETWEEN 1 AND 1023),
  envelope_bytes      TEXT   NOT NULL CHECK (length(envelope_bytes) BETWEEN 1 AND 3071),
  envelope_sha256     BYTEA  NOT NULL CHECK (length(envelope_sha256) = 32),
  manifest_sha256     BYTEA  NOT NULL CHECK (length(manifest_sha256) = 32),
  trust_bundle_sha256 BYTEA  NOT NULL CHECK (length(trust_bundle_sha256) = 32),
  fetched_at          BIGINT NOT NULL CHECK (fetched_at >= 0)
);
